const typedColumnIdentities = new Set<ModeledColumnIdentity>();
for (const [type, identities] of Object.entries(
  modeled0003ColumnIdentitiesByType,
)) {
  for (const identity of identities) {
    if (typedColumnIdentities.has(identity)) {
      throw new Error("duplicate modeled column type identity: " + identity);
    }
    typedColumnIdentities.add(identity);
    const column = modeled0003ColumnCatalog.find(
      (candidate) =>
        candidate.relationName + "." + candidate.columnName === identity,
    );
    if (column === undefined || column.type !== type) {
      throw new Error("modeled column type inventory mismatch: " + identity);
    }
  }
}

if (typedColumnIdentities.size !== modeled0003ColumnCatalog.length) {
  throw new Error("modeled column type inventory is not an exact closure");
}
if (
  modeled0003NullableColumnIdentities.size +
    modeled0003NonNullableColumnIdentities.size !==
  modeled0003ColumnCatalog.length
) {
  throw new Error(
    "modeled column nullability inventory is not an exact closure",
  );
}
for (const column of modeled0003ColumnCatalog) {
  const identity = (column.relationName +
    "." +
    column.columnName) as ModeledColumnIdentity;
  const nullable = modeled0003NullableColumnIdentities.has(identity);
  const nonNullable = modeled0003NonNullableColumnIdentities.has(identity);
  if (nullable === nonNullable || column.nullable !== nullable) {
    throw new Error(
      "modeled column nullability inventory mismatch: " + identity,
    );
  }
}

